   491      heapcm = 0;
   492      if (d == 32 || d == 16) {   /* 24 bpp rgb or 16 bpp: no colormap */
   493          ncolors = 0;
   494          cmaplen = 0;
   495      } else if ((cmap = pixGetColormap(pix))) {   /* existing colormap */
   496          ncolors = pixcmapGetCount(cmap);
   497          cmaplen = ncolors * sizeof(RGBA_QUAD);
   498          cta = (l_uint8 *)cmap->array;
   499      } else {   /* no existing colormap; d <= 8; make a binary or gray one */
   500          if (d == 1) {
   501              cmaplen  = sizeof(bwmap);
   502              ncolors = 2;
   503              cta = (l_uint8 *)bwmap;
   504          } else {   /* d = 2,4,8; use a grayscale output colormap */
   505              ncolors = 1 << fdepth;
   506              cmaplen = ncolors * sizeof(RGBA_QUAD);
   507              heapcm = 1;
   508              cta = (l_uint8 *)LEPT_CALLOC(cmaplen, 1);
   509              stepsize = 255 / (ncolors - 1);
   510              for (i = 0, val = 0, pquad = (RGBA_QUAD *)cta;
   511                   i < ncolors;
   512                   i++, val += stepsize, pquad++) {
   513                  pquad->blue = pquad->green = pquad->red = val;
   514                  pquad->alpha = 255;  /* opaque */
   515              }
   516          }
   517      }
