  1891  {
  1892  PIX  *pixd;
  1893
  1894      PROCNAME("pixUnpackBinary");
  1895
  1896      if (!pixs)
  1897          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  1898      if (pixGetDepth(pixs) != 1)
  1899          return (PIX *)ERROR_PTR("pixs not 1 bpp", procName, NULL);
  1900      if (depth != 2 && depth != 4 && depth != 8 && depth != 16 && depth != 32)
  1901          return (PIX *)ERROR_PTR("depth not 2, 4, 8, 16 or 32 bpp",
  1902                                  procName, NULL);
  1903
  1904      if (depth == 2) {
  1905          if (invert == 0)
  1906              pixd = pixConvert1To2(NULL, pixs, 0, 3);
  1907          else  /* invert bits */
  1908              pixd = pixConvert1To2(NULL, pixs, 3, 0);
  1909      } else if (depth == 4) {
  1910          if (invert == 0)
  1911              pixd = pixConvert1To4(NULL, pixs, 0, 15);
  1912          else  /* invert bits */
  1913              pixd = pixConvert1To4(NULL, pixs, 15, 0);
  1914      } else if (depth == 8) {
  1915          if (invert == 0)
  1916              pixd = pixConvert1To8(NULL, pixs, 0, 255);
  1917          else  /* invert bits */
  1918              pixd = pixConvert1To8(NULL, pixs, 255, 0);
  1919      } else if (depth == 16) {
  1920          if (invert == 0)
  1921              pixd = pixConvert1To16(NULL, pixs, 0, 0xffff);
  1922          else  /* invert bits */
  1923              pixd = pixConvert1To16(NULL, pixs, 0xffff, 0);
  1924      } else {
  1925          if (invert == 0)
  1926              pixd = pixConvert1To32(NULL, pixs, 0, 0xffffffff);
  1927          else  /* invert bits */
  1928              pixd = pixConvert1To32(NULL, pixs, 0xffffffff, 0);
  1929      }
  1930
  1931      pixCopyInputFormat(pixd, pixs);
  1932      return pixd;
  1933  }
