  1935
  1936  /*!
  1937   * \brief   pixConvert1To16()
--
  2480
  2481      PROCNAME("pixConvert2To8");
  2482
  2483      if (!pixs)
  2484          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  2485      if (pixGetDepth(pixs) != 2)
  2486          return (PIX *)ERROR_PTR("pixs not 2 bpp", procName, NULL);
  2487
  2488      cmaps = pixGetColormap(pixs);
  2489      if (cmaps && cmapflag == FALSE)
  2490          return pixRemoveColormap(pixs, REMOVE_CMAP_TO_GRAYSCALE);
  2491
  2492      pixGetDimensions(pixs, &w, &h, NULL);
  2493      if ((pixd = pixCreate(w, h, 8)) == NULL)
  2494          return (PIX *)ERROR_PTR("pixd not made", procName, NULL);
  2495      pixSetPadBits(pixs, 0);
  2496      pixCopyResolution(pixd, pixs);
  2497      pixCopyInputFormat(pixd, pixs);
  2498      datas = pixGetData(pixs);
  2499      wpls = pixGetWpl(pixs);
  2500      datad = pixGetData(pixd);
  2501      wpld = pixGetWpl(pixd);
  2502
  2503      if (cmapflag == TRUE) {  /* pixd will have a colormap */
  2504          if (cmaps) {  /* use the existing colormap from pixs */
  2505              cmapd = pixcmapConvertTo8(cmaps);
  2506          } else {  /* make a colormap from the input values */
  2507              cmapd = pixcmapCreate(8);
  2508              pixcmapAddColor(cmapd, val0, val0, val0);
  2509              pixcmapAddColor(cmapd, val1, val1, val1);
  2510              pixcmapAddColor(cmapd, val2, val2, val2);
  2511              pixcmapAddColor(cmapd, val3, val3, val3);
  2512          }
  2513          pixSetColormap(pixd, cmapd);
  2514          for (i = 0; i < h; i++) {
  2515              lines = datas + i * wpls;
  2516              lined = datad + i * wpld;
  2517              for (j = 0; j < w; j++) {
  2518                  dibit = GET_DATA_DIBIT(lines, j);
  2519                  SET_DATA_BYTE(lined, j, dibit);
  2520              }
  2521          }
  2522          return pixd;
  2523      }
  2524
  2525          /* Last case: no colormap in either pixs or pixd.
  2526           * Use input values and build a table to convert 1 src byte
  2527           * (4 src pixels) at a time */
  2528      tab = (l_uint32 *)LEPT_CALLOC(256, sizeof(l_uint32));
  2529      val[0] = val0;
  2530      val[1] = val1;
  2531      val[2] = val2;
  2532      val[3] = val3;
  2533      for (index = 0; index < 256; index++) {
  2534          tab[index] = (val[(index >> 6) & 3] << 24) |
  2535                       (val[(index >> 4) & 3] << 16) |
  2536                       (val[(index >> 2) & 3] << 8) | val[index & 3];
  2537      }
  2538
  2539      nbytes = (w + 3) / 4;
  2540      for (i = 0; i < h; i++) {
  2541          lines = datas + i * wpls;
  2542          lined = datad + i * wpld;
  2543          for (j = 0; j < nbytes; j++) {
  2544              byte = GET_DATA_BYTE(lines, j);
  2545              lined[j] = tab[byte];
  2546          }
  2547      }
  2548
  2549      LEPT_FREE(tab);
  2550      return pixd;
  2551  }
