  2553
  2554  /*!
  2555   * \brief   pixConvert4To8()
  2556   *
  2557   * \param[in]    pixs      4 bpp
  2558   * \param[in]    cmapflag  TRUE if pixd is to have a colormap; FALSE otherwise
  2559   * \return  pixd 8 bpp, or NULL on error
  2560   *
  2561   * <pre>
  2562   * Notes:
  2563   *      ~ If cmapflag is TRUE:
  2564   *          ~ pixd is made with a colormap.
  2565   *          ~ If pixs has a colormap, it is copied and the colormap
  2566   *            index values are placed in pixd.
  2567   *          ~ If pixs does not have a colormap, a colormap with linear
  2568   *            trc is built and the pixel values in pixs are placed in
  2569   *            pixd as colormap index values.
  2570   *      ~ If cmapflag is FALSE:
  2571   *          ~ pixd is made without a colormap.
  2572   *          ~ If pixs has a colormap, it is removed and the values stored
  2573   *            in pixd are from the colormap (converted to gray).
  2574   *          ~ If pixs does not have a colormap, the pixel values in pixs
  2575   *            are used, with shift replication, to populate pixd.
  2576   * </pre>
  2577   */
  2578  PIX *
  2579  pixConvert4To8(PIX     *pixs,
  2580                 l_int32  cmapflag)
  2581  {
  2582  l_int32    w, h, i, j, wpls, wpld, byte, qbit;
  2583  l_uint32  *datas, *datad, *lines, *lined;
  2584  PIX       *pixd;
  2585  PIXCMAP   *cmaps, *cmapd;
  2586
  2587      PROCNAME("pixConvert4To8");
  2588
  2589      if (!pixs)
  2590          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  2591      if (pixGetDepth(pixs) != 4)
  2592          return (PIX *)ERROR_PTR("pixs not 4 bpp", procName, NULL);
  2593
  2594      cmaps = pixGetColormap(pixs);
  2595      if (cmaps && cmapflag == FALSE)
  2596          return pixRemoveColormap(pixs, REMOVE_CMAP_TO_GRAYSCALE);
  2597
  2598      pixGetDimensions(pixs, &w, &h, NULL);
  2599      if ((pixd = pixCreate(w, h, 8)) == NULL)
  2600          return (PIX *)ERROR_PTR("pixd not made", procName, NULL);
  2601      pixCopyResolution(pixd, pixs);
  2602      pixCopyInputFormat(pixd, pixs);
  2603      datas = pixGetData(pixs);
  2604      wpls = pixGetWpl(pixs);
  2605      datad = pixGetData(pixd);
  2606      wpld = pixGetWpl(pixd);
  2607
  2608      if (cmapflag == TRUE) {  /* pixd will have a colormap */
  2609          if (cmaps) {  /* use the existing colormap from pixs */
  2610              cmapd = pixcmapConvertTo8(cmaps);
  2611          } else {  /* make a colormap with a linear trc */
  2612              cmapd = pixcmapCreate(8);
  2613              for (i = 0; i < 16; i++)
  2614                  pixcmapAddColor(cmapd, 17 * i, 17 * i, 17 * i);
  2615          }
  2616          pixSetColormap(pixd, cmapd);
  2617          for (i = 0; i < h; i++) {
  2618              lines = datas + i * wpls;
  2619              lined = datad + i * wpld;
  2620              for (j = 0; j < w; j++) {
  2621                  qbit = GET_DATA_QBIT(lines, j);
  2622                  SET_DATA_BYTE(lined, j, qbit);
  2623              }
  2624          }
  2625          return pixd;
  2626      }
  2627
  2628          /* Last case: no colormap in either pixs or pixd.
  2629           * Replicate the qbit value into 8 bits. */
  2630      for (i = 0; i < h; i++) {
  2631          lines = datas + i * wpls;
  2632          lined = datad + i * wpld;
  2633          for (j = 0; j < w; j++) {
  2634              qbit = GET_DATA_QBIT(lines, j);
  2635              byte = (qbit << 4) | qbit;
  2636              SET_DATA_BYTE(lined, j, byte);
  2637          }
  2638      }
  2639      return pixd;
  2640  }
