  2769
  2770  /*!
  2771   * \brief   pixConvert8To2()
  2772   *
  2773   * \param[in]     pix     8 bpp; colormap OK
  2774   * \return  pixd  2 bpp, or NULL on error
  2775   *
  2776   * <pre>
  2777   * Notes:
  2778   *      (1) Any existing colormap is removed to gray.
  2779   * </pre>
  2780   */
  2781  PIX *
  2782  pixConvert8To2(PIX  *pix)
  2783  {
  2784  l_int32    i, j, w, h, wpls, wpld;
  2785  l_uint32   word;
  2786  l_uint32  *datas, *lines, *datad, *lined;
  2787  PIX       *pixs, *pixd;
  2788
  2789      PROCNAME("pixConvert8To2");
  2790
  2791      if (!pix || pixGetDepth(pix) != 8)
  2792          return (PIX *)ERROR_PTR("pix undefined or not 8 bpp", procName, NULL);
  2793
  2794      if (pixGetColormap(pix) != NULL)
  2795          pixs = pixRemoveColormap(pix, REMOVE_CMAP_TO_GRAYSCALE);
  2796      else
  2797          pixs = pixClone(pix);
  2798      pixGetDimensions(pixs, &w, &h, NULL);
  2799      datas = pixGetData(pixs);
  2800      wpls = pixGetWpl(pixs);
  2801      pixd = pixCreate(w, h, 2);
  2802      datad = pixGetData(pixd);
  2803      wpld = pixGetWpl(pixd);
  2804      for (i = 0; i < h; i++) {
  2805          lines = datas + i * wpls;
  2806          lined = datad + i * wpld;
  2807          for (j = 0; j < wpls; j++) {  /* march through 4 pixels at a time */
  2808              word = lines[j] & 0xc0c0c0c0;  /* top 2 bits of each byte */
  2809              word = (word >> 24) | ((word & 0xff0000) >> 18) |
  2810                     ((word & 0xff00) >> 12) | ((word & 0xff) >> 6);
  2811              SET_DATA_BYTE(lined, j, word);  /* only LS byte is filled */
  2812          }
  2813      }
  2814      pixDestroy(&pixs);
  2815      return pixd;
  2816  }
