  2836   */
  2837  PIX *
  2838  pixConvertTo4(PIX  *pixs)
  2839  {
  2840  l_int32  d;
  2841  PIX     *pix1, *pix2, *pix3, *pixd;
  2842
  2843      PROCNAME("pixConvertTo4");
