  2887   * </pre>
  2888   */
  2889  PIX *
  2890  pixConvert8To4(PIX  *pix)
  2891  {
  2892  l_int32    i, j, w, h, wpls, wpld, val;
  2893  l_uint32  *datas, *lines, *datad, *lined;
  2894  PIX       *pixs, *pixd;
  2895
  2896      PROCNAME("pixConvert8To4");
  2897
  2898      if (!pix || pixGetDepth(pix) != 8)
  2899          return (PIX *)ERROR_PTR("pix undefined or not 8 bpp", procName, NULL);
  2900
  2901      if (pixGetColormap(pix) != NULL)
  2902          pixs = pixRemoveColormap(pix, REMOVE_CMAP_TO_GRAYSCALE);
  2903      else
  2904          pixs = pixClone(pix);
  2905      pixGetDimensions(pixs, &w, &h, NULL);
  2906      datas = pixGetData(pixs);
  2907      wpls = pixGetWpl(pixs);
  2908      pixd = pixCreate(w, h, 4);
  2909      datad = pixGetData(pixd);
  2910      wpld = pixGetWpl(pixd);
  2911      for (i = 0; i < h; i++) {
  2912          lines = datas + i * wpls;
  2913          lined = datad + i * wpld;
  2914          for (j = 0; j < w; j++) {
  2915              val = GET_DATA_BYTE(lines, j);
  2916              val = val >> 4;  /* take top 4 bits */
  2917              SET_DATA_QBIT(lined, j, val);
  2918          }
  2919      }
  2920      pixDestroy(&pixs);
  2921      return pixd;
  2922  }
