  2925  /*---------------------------------------------------------------------------*
  2926   *                     Top-level conversion to 1 bpp                         *
  2927   *---------------------------------------------------------------------------*/
  2928  /*!
  2929   * \brief   pixConvertTo1Adaptive()
  2930   *
  2931   * \param[in]    pixs       1, 2, 4, 8, 16 or 32 bpp
  2932   * \return  pixd 1 bpp, or NULL on error
  2933   *
  2934   * <pre>
  2935   * Notes:
  2936   *      (1) This is a top-level function, that uses default values for
  2937   *          adaptive thresholding, if necessary.  Otherwise, it is the same as
  2938   *          pixConvertTo1(), which uses a global threshold for binarization.
  2939   * </pre>
  2940   */
  2941  PIX *
  2942  pixConvertTo1Adaptive(PIX     *pixs)
  2943  {
  2944  l_int32   d, color0, color1, rval, gval, bval;
  2945  PIX      *pix1, *pix2, *pixd;
  2946  PIXCMAP  *cmap;
  2947
  2948      PROCNAME("pixConvertTo1Adaptive");
  2949
  2950      if (!pixs)
  2951          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  2952      d = pixGetDepth(pixs);
  2953      if (d != 1 && d != 2 && d != 4 && d != 8 && d != 16 && d != 32)
  2954          return (PIX *)ERROR_PTR("depth not {1,2,4,8,16,32}", procName, NULL);
  2955
  2956      cmap = pixGetColormap(pixs);
  2957      if (d == 1) {
  2958          if (!cmap) {
  2959              return pixCopy(NULL, pixs);
  2960          } else {  /* strip the colormap off, and invert if reasonable
  2961                     for standard binary photometry.  */
  2962              pixcmapGetColor(cmap, 0, &rval, &gval, &bval);
  2963              color0 = rval + gval + bval;
