  4125
  4126  /*!
  4127   * \brief   pixConvertColorToSubpixelRGB()
  4128   *
  4129   * \param[in]    pixs            32 bpp or colormapped
  4130   * \param[in]    scalex, scaley
  4131   * \param[in]    order           of subpixel rgb color components in
  4132   *                               composition of pixd:
  4133   *                               L_SUBPIXEL_ORDER_RGB, L_SUBPIXEL_ORDER_BGR,
  4134   *                               L_SUBPIXEL_ORDER_VRGB, L_SUBPIXEL_ORDER_VBGR
  4135   * \return  pixd 32 bpp, or NULL on error
  4136   *
  4137   * <pre>
  4138   * Notes:
  4139   *      (1) If pixs has a colormap, it is removed to 32 bpp rgb.
  4140   *          If the colormap has no color, pixConvertGrayToSubpixelRGB()
  4141   *          should be called instead, because it will give the same result
  4142   *          more efficiently.  The function pixConvertToSubpixelRGB()
  4143   *          will do the best thing for all cases.
  4144   *      (2) For horizontal subpixel splitting, the input rgb image
  4145   *          is rescaled by %scaley vertically and by 3.0 times
  4146   *          %scalex horizontally.  Then for each horizontal triplet
  4147   *          of pixels, the r component of the final pixel is selected
  4148   *          from the r component of the appropriate pixel in the triplet,
  4149   *          and likewise for g and b.  Vertical subpixel splitting is
  4150   *          handled similarly.
  4151   * </pre>
  4152   */
  4153  PIX *
  4154  pixConvertColorToSubpixelRGB(PIX       *pixs,
  4155                               l_float32  scalex,
  4156                               l_float32  scaley,
  4157                               l_int32    order)
  4158  {
  4159  l_int32    w, h, d, wd, hd, wplt, wpld, i, j, rval, gval, bval, direction;
  4160  l_uint32  *datat, *datad, *linet, *lined;
  4161  PIX       *pix1, *pix2, *pixd;
  4162  PIXCMAP   *cmap;
  4163
  4164      PROCNAME("pixConvertColorToSubpixelRGB");
  4165
  4166      if (!pixs)
  4167          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  4168      d = pixGetDepth(pixs);
  4169      cmap = pixGetColormap(pixs);
  4170      if (d != 32 && !cmap)
  4171          return (PIX *)ERROR_PTR("pix not 32 bpp & not cmapped", procName, NULL);
  4172      if (scalex <= 0.0 || scaley <= 0.0)
  4173          return (PIX *)ERROR_PTR("scale factors must be > 0", procName, NULL);
  4174      if (order != L_SUBPIXEL_ORDER_RGB && order != L_SUBPIXEL_ORDER_BGR &&
  4175          order != L_SUBPIXEL_ORDER_VRGB && order != L_SUBPIXEL_ORDER_VBGR)
  4176          return (PIX *)ERROR_PTR("invalid subpixel order", procName, NULL);
  4177
  4178      direction =
  4179          (order == L_SUBPIXEL_ORDER_RGB || order == L_SUBPIXEL_ORDER_BGR)
  4180          ? L_HORIZ : L_VERT;
  4181      pix1 = pixRemoveColormap(pixs, REMOVE_CMAP_TO_FULL_COLOR);
  4182      if (direction == L_HORIZ)
  4183          pix2 = pixScale(pix1, 3.0 * scalex, scaley);
  4184      else  /* L_VERT */
  4185          pix2 = pixScale(pix1, scalex, 3.0 * scaley);
  4186
  4187      pixGetDimensions(pix2, &w, &h, NULL);
  4188      wd = (direction == L_HORIZ) ? w / 3 : w;
  4189      hd = (direction == L_VERT) ? h / 3 : h;
  4190      pixd = pixCreate(wd, hd, 32);
  4191      pixCopyInputFormat(pixd, pixs);
  4192      datad = pixGetData(pixd);
  4193      wpld = pixGetWpl(pixd);
  4194      datat = pixGetData(pix2);
  4195      wplt = pixGetWpl(pix2);
  4196      if (direction == L_HORIZ) {
  4197          for (i = 0; i < hd; i++) {
  4198              linet = datat + i * wplt;
  4199              lined = datad + i * wpld;
  4200              for (j = 0; j < wd; j++) {
  4201                  if (order == L_SUBPIXEL_ORDER_RGB) {
  4202                      extractRGBValues(linet[3 * j], &rval, NULL, NULL);
  4203                      extractRGBValues(linet[3 * j + 1], NULL, &gval, NULL);
  4204                      extractRGBValues(linet[3 * j + 2], NULL, NULL, &bval);
  4205                  } else {  /* order BGR */
  4206                      extractRGBValues(linet[3 * j], NULL, NULL, &bval);
  4207                      extractRGBValues(linet[3 * j + 1], NULL, &gval, NULL);
  4208                      extractRGBValues(linet[3 * j + 2], &rval, NULL, NULL);
  4209                  }
  4210                  composeRGBPixel(rval, gval, bval, &lined[j]);
  4211              }
  4212          }
  4213      } else {  /* L_VERT */
  4214          for (i = 0; i < hd; i++) {
  4215              linet = datat + 3 * i * wplt;
  4216              lined = datad + i * wpld;
  4217              for (j = 0; j < wd; j++) {
  4218                  if (order == L_SUBPIXEL_ORDER_VRGB) {
  4219                      extractRGBValues(linet[j], &rval, NULL, NULL);
  4220                      extractRGBValues((linet + wplt)[j], NULL, &gval, NULL);
  4221                      extractRGBValues((linet + 2 * wplt)[j], NULL, NULL, &bval);
  4222                  } else {  /* order VBGR */
  4223                      extractRGBValues(linet[j], NULL, NULL, &bval);
  4224                      extractRGBValues((linet + wplt)[j], NULL, &gval, NULL);
  4225                      extractRGBValues((linet + 2 * wplt)[j], &rval, NULL, NULL);
  4226                  }
  4227                  composeRGBPixel(rval, gval, bval, &lined[j]);
  4228              }
  4229          }
  4230      }
  4231
  4232      if (pixGetSpp(pixs) == 4)
  4233          pixScaleAndTransferAlpha(pixd, pixs, scalex, scaley);
  4234
  4235      pixDestroy(&pix1);
  4236      pixDestroy(&pix2);
  4237      return pixd;
  4238  }
